module multi_pipe_4bit #(
    parameter size = 4,
    parameter N = 2 * size
) (
    input 						clk,
    input 						rst_n,
    input	[size-1:0]			mul_a,
    input	[size-1:0]			mul_b,
    output	reg	[size*2-1:0]	mul_out
);

    wire [7:0] mul_a_ext, mul_b_ext;
    assign mul_a_ext = {4'd0, mul_a};
    assign mul_b_ext = {4'd0, mul_b};

    wire [7:0] partial_product[0:3];
    assign partial_product[0] = (mul_b_ext[0]) ? (mul_a_ext << 0) : 'd0;
    assign partial_product[1] = (mul_b_ext[1]) ? (mul_a_ext << 1) : 'd0;
    assign partial_product[2] = (mul_b_ext[2]) ? (mul_a_ext << 2) : 'd0;
    assign partial_product[3] = (mul_b_ext[3]) ? (mul_a_ext << 3) : 'd0;

    reg [7:0] reg_sum[0:3];
    integer j;
    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            for(j = 0; j < 4; j=j+1) begin
                reg_sum[j] <= 8'd0;
            end
        end else begin
            reg_sum[0] <= partial_product[0];
            for(j = 1; j < 4; j=j+1) begin
                reg_sum[j] <= reg_sum[j-1] + partial_product[j];
            end
        end
    end

    reg [7:0] product;
    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            product <= 8'd0;
        end else begin
            product <= reg_sum[3];
        end
    end

    assign mul_out = product;
endmodule
